#include "color_picker_scheme.h"
#include <iostream>
#include <stdexcept>
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{using namespace moon;CHECK(parseColorPickerScheme("hs-square")==ColorPickerScheme::HsSquare);CHECK(parseColorPickerScheme("future-mode")==ColorPickerScheme::SvSquare);PickerRole r;r.hsv={37,.4,.5};r.color=0x37000000;r.emit();pickerSchemeSetField(r,ColorPickerScheme::HsSquare,2./3,0);CHECK(r.hsv.h==240&&r.hsv.s==1&&r.hsv.v==.5&&r.color==0x37800000);auto m=pickerSchemeMarker(ColorPickerScheme::HsSquare,r.hsv);CHECK(m.first==2./3&&m.second==0);pickerSchemeSetStripValue(r,ColorPickerScheme::HsSquare,0);CHECK(r.color==0x37000000&&r.hsv.h==240&&r.hsv.s==1);r.sync(r.color);pickerSchemeSetStripValue(r,ColorPickerScheme::HsSquare,1000);CHECK(r.color==0x37ff0000);pickerSchemeSetField(r,ColorPickerScheme::HsSquare,1,1);CHECK(r.color==0x37ffffff&&r.hsv.h==0&&r.hsv.s==0);CHECK(pickerSchemeStripMaximum(ColorPickerScheme::HsSquare)==1000);CHECK(pickerSchemeStripValue(ColorPickerScheme::HsSquare,{0,0,.1234})==123);for(int h=0;h<360;++h){pickerSchemeSetStripValue(r,ColorPickerScheme::SvSquare,h);CHECK(r.hsv.h==h);}std::cout<<"SV/HS axes, endpoints, alpha, own echo, value restoration passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
